records = []
for number in range(1,21):
    pid = f'P{number:02d}'
    if pid in crossref:
        item = crossref[pid]
        assert item['status'] == 'verified', pid
        m = item['metadata']
        rec = dict(id=pid, title=html.unescape(m['title'][0]), authors=[a['family']+', '+a.get('given','') for a in m['author']], year=m['published']['date-parts'][0][0], venue=html.unescape(m.get('container-title',[''])[0]), doi=m['DOI'], url='https://doi.org/'+m['DOI'], type='article', metadata_status='verified', metadata_sources=[item['source']], version_note='Final metadata verified; see method-access statement.')
        for field, source in [('volume','volume'),('number','issue'),('pages','page')]:
            if m.get(source): rec[field]=m[source].replace('-', '--') if field=='pages' else m[source]
        if pid in ['P09','P13','P15','P17']: rec['type']='inproceedings'
        if pid == 'P07': rec.update(type='incollection',venue='Big Data Technologies and Applications',version_note='2020 precursor and 2021 chapter are one research line.')
        if pid == 'P08': rec.update(year=2022,version_note='Online 2021-11-10; volume 27 issue 1 published 2022. P07 is a related predecessor, not an additional version of this DOI.')
        if pid == 'P01': rec['version_note']='Final authors verified by Crossref/UQ; do not reuse precursor author list. Precursor title is Temporal Analysis of NetFlow Datasets for Network Intrusion Detection Systems.'
        if pid == 'P11': rec['version_note']='Precursor title On Generalisability of Machine Learning-based Network Intrusion Detection Systems; final and precursor counted once.'
        if pid == 'P16': rec.update(volume='8',number='4',pages='1559--1582',version_note='Publisher page provides volume/issue/full page range; Crossref gives incomplete page field.')
    else:
        rec = dict(id=pid, **extras[pid], metadata_status='verified')
        rec.setdefault('url','https://arxiv.org/abs/'+preprints[pid])
        rec['metadata_sources']=[rec['url']]
    if pid in preprints:
        rec['arxiv_id']=preprints[pid]
        rec['metadata_sources'].append('https://arxiv.org/abs/'+preprints[pid])
    rec['method']={field:NOTES[pid].get(field,'not verified') for field in FIELDS}
    rec['checked_date']='2026-09-05'
    rec['access_scope']=('Selected primary full-text sections' if pid in ['P01','P02','P05','P11'] else 'Primary publisher indexed methods and author repository; complete direct article inaccessible' if pid=='P03' else 'Publisher indexed abstract/section excerpts, full article inaccessible' if pid=='P04' else 'Publisher abstract, full PDF inaccessible' if pid=='P16' else 'Primary metadata and/or abstract; full methods not inspected')
    records.append(rec)

data={'review_date':'2026-09-05','review_type':'targeted review, not systematic review','count':20,'deduplication':'Preprints and final articles merged by research line. P07/P08 retained as distinct development stages with overlap disclosed.','papers':records,'watchlist_file':'watchlist.md','limitations':'Metadata verification is not method replication, quality endorsement, or Scopus verification. Missing evidence is not evidence of novelty.'}
payload=json.dumps(data,indent=2,ensure_ascii=False)+'\n'
(ROOT/'related_papers_20.json').write_text(payload,encoding='utf-8')
(ROOT.parent/'related_papers_20.json').write_text(payload,encoding='utf-8')

intro='''# Related-work matrix: 20 research lines\n\nChecked 5 September 2026. This is a targeted review, not a systematic review or reproduction. `not verified` means evidence was not inspected; `not reported` is restricted to the inspected section. Neither establishes absence from the complete literature. Metadata are stored in `primary_metadata_crossref.json`; version-specific details in `related_papers_20.json`. P01 and P11 method evidence comes from precursors, not silently from the final article. P03 evidence is the authors\' current repository, not a verified publication snapshot. No scores are treated as directly comparable.\n\n'''
labels=['ID / source','dataset version','target','model','feature set','split / group / time order','preprocessing fit access','labels: training / selection / calibration','source / target adaptation','target FPR','traffic-composition diagnosis','ablations','hardware','cost','code','limitations','section / page evidence']
lines=[intro,'| '+' | '.join(labels)+' |','| '+' | '.join(['---']*len(labels))+' |']
for rec in records:
    cells=[f"[{rec['id']}]({rec['url']})"]+[str(rec['method'][f]).replace('|','/').replace('\n',' ') for f in FIELDS]
    lines.append('| '+' | '.join(cells)+' |')
lines += ['','## Access and version register','']
source_overrides={'P01':'https://arxiv.org/html/2503.04404v1','P02':'https://arxiv.org/html/2509.16625v6','P03':'https://github.com/Ricco555/TE-G-SAGE-XAI','P04':'https://www.sciencedirect.com/science/article/abs/pii/S187454822600048X','P05':'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0346801','P11':'https://arxiv.org/html/2205.04112v1','P16':'https://journal.50sea.com/index.php/IJIST/article/view/1956'}
for rec in records:
    src=source_overrides.get(rec['id'],rec['url'])
    lines.append(f"- **{rec['id']}** [{rec['title']}]({src}). {rec['access_scope']}. {rec['version_note']}")
lines += ['','Additional close work found beyond the initial list is in [watchlist.md](watchlist.md). Review it before a novelty claim; the 20 seeds do not bound the literature.','']
(ROOT/'related_work_matrix.md').write_text('\n'.join(lines),encoding='utf-8')

def escape(s):
    return str(s).replace('&',r'\&').replace('%',r'\%').replace('_',r'\_')
bib=['% Verified primary metadata; 20 research lines, precursors not double-counted.','% UTF-8 bibliography. Method access is documented separately; a citation is not full-text verification.','']
for rec in records:
    b={'author':' and '.join(rec['authors']),'title':'{'+rec['title']+'}','year':rec['year'],'url':rec['url']}
    if rec['type']=='article': b['journal']=rec['venue']
    elif rec['type'] in ['inproceedings','incollection']: b['booktitle']=rec['venue']
    for f in ['doi','volume','number','pages']:
        if rec.get(f): b[f]=rec[f]
    if rec.get('arxiv_id'):
        b['eprint']=rec['arxiv_id']; b['archivePrefix']='arXiv'
    b['note']=rec['version_note']
    bib.append('@'+rec['type']+'{'+rec['id']+',\n'+',\n'.join('  '+k+' = {'+(str(v) if k in ['url','doi','eprint'] else escape(v))+'}' for k,v in b.items())+'\n}\n')
(ROOT/'references.bib').write_text('\n'.join(bib),encoding='utf-8')
print('Wrote 20 verified records, matrix, and bibliography.')
